      "area": "Observability & Monitoring",
      "points": [
        "Log suspicious inputs in a privacy-preserving way to detect attack patterns without exposing user data.",
        "Monitor for anomalies in API usage, error rates, and unusual query shapes.",
        "Implement alerting for repeated NoSQL injection attempts or CSP violations."
      ]
    },
