      "title": "Client-side safe HTML rendering in React",
      "code": "import DOMPurify from 'dompurify';\n\nfunction SafeHtml({ html }) {\n  const clean = DOMPurify.sanitize(html);\n  return <div dangerouslySetInnerHTML={{ __html: clean }} />;\n}\n"
    },
